import{_ as a,o as s,c as t,a2 as i}from"./chunks/framework.CyZTVJbV.js";const k=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"en/faq.md","filePath":"en/faq.md"}'),o={name:"en/faq.md"};function n(l,e,r,d,p,c){return s(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><blockquote><p><a href="./faq">🇬🇧 English</a> • <a href="./../ja/faq">🇯🇵 日本語</a></p></blockquote><h2 id="q1-why-kiwa-over-synpress-or-metamask-test-dapp" tabindex="-1">Q1: Why kiwa over Synpress or MetaMask Test Dapp? <a class="header-anchor" href="#q1-why-kiwa-over-synpress-or-metamask-test-dapp" aria-label="Permalink to &quot;Q1: Why kiwa over Synpress or MetaMask Test Dapp?&quot;">​</a></h2><p>A: Existing tools mostly drive the MetaMask extension. Reproducing wallet popup UI in CI tends to be flaky. kiwa keeps wallet behavior <strong>inside code</strong>, skipping popup / approve UIs, and prioritizes CI stability. See <a href="./../COMPARISON">docs/COMPARISON.md</a>.</p><h2 id="q2-anvil-does-not-start-anvil-not-found-in-path" tabindex="-1">Q2: anvil does not start (<code>anvil not found in PATH</code>) <a class="header-anchor" href="#q2-anvil-does-not-start-anvil-not-found-in-path" aria-label="Permalink to &quot;Q2: anvil does not start (`anvil not found in PATH`)&quot;">​</a></h2><p>A: Install Foundry and make sure it is on PATH.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://foundry.paradigm.xyz</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">foundryup</span></span></code></pre></div><h2 id="q3-port-8545-is-already-used" tabindex="-1">Q3: Port 8545 is already used <a class="header-anchor" href="#q3-port-8545-is-already-used" aria-label="Permalink to &quot;Q3: Port 8545 is already used&quot;">​</a></h2><p>A: Another anvil instance is likely already running. Kill it or pass another port via <code>startAnvil({ port: 8546 })</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lsof</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -iTCP:8545</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -sTCP:LISTEN</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">kill</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">PI</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">D</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><h2 id="q4-tests-fail-with-stake-balance-loading" tabindex="-1">Q4: Tests fail with stake-balance: (loading) <a class="header-anchor" href="#q4-tests-fail-with-stake-balance-loading" aria-label="Permalink to &quot;Q4: Tests fail with stake-balance: (loading)&quot;">​</a></h2><p>A: Your <code>.env.local</code> contract addresses may not have been baked in during build. Next.js inlines <code>.env.local</code> at build time, so addresses written by global-setup are not reflected until the next build. Either write <code>.env.local</code> via <code>pretest</code> or clear the build cache (<code>rm -rf .next</code>).</p><h2 id="q5-multiple-examples-collide-on-ports" tabindex="-1">Q5: Multiple examples collide on ports <a class="header-anchor" href="#q5-multiple-examples-collide-on-ports" aria-label="Permalink to &quot;Q5: Multiple examples collide on ports&quot;">​</a></h2><p>A: Use unique ports per example (3033-3047). See each example&#39;s <code>package.json</code> <code>scripts.dev</code> / <code>start</code>. Anvil shares port 8545 by default, so parallel runs across examples are not supported.</p><h2 id="q6-i-want-to-use-connectkit-reown-instead-of-wagmi-v2-rainbowkit-v2" tabindex="-1">Q6: I want to use ConnectKit / Reown instead of wagmi v2 + RainbowKit v2 <a class="header-anchor" href="#q6-i-want-to-use-connectkit-reown-instead-of-wagmi-v2-rainbowkit-v2" aria-label="Permalink to &quot;Q6: I want to use ConnectKit / Reown instead of wagmi v2 + RainbowKit v2&quot;">​</a></h2><p>A: kiwa conforms to EIP-1193 / EIP-6963 standards, so it works with any wallet picker. For specific picker testing, see <code>examples/basic-connect/tests/eip6963.spec.ts</code>.</p><h2 id="q7-contract-deploys-are-slow" tabindex="-1">Q7: Contract deploys are slow <a class="header-anchor" href="#q7-contract-deploys-are-slow" aria-label="Permalink to &quot;Q7: Contract deploys are slow&quot;">​</a></h2><p>A: Anvil&#39;s deterministic deploys (fixed deployer + sequential nonce) yield the same addresses every run. Commit the deploy artifacts (<code>forge-out/</code>) to skip <code>forge build</code> and speed things up.</p><h2 id="q8-how-do-i-test-time-dependent-code" tabindex="-1">Q8: How do I test time-dependent code? <a class="header-anchor" href="#q8-how-do-i-test-time-dependent-code" aria-label="Permalink to &quot;Q8: How do I test time-dependent code?&quot;">​</a></h2><p>A: Use anvil RPCs <code>evm_snapshot</code> / <code>evm_revert</code> / <code>evm_increaseTime</code>. See <a href="./cookbook/time-manipulation">Cookbook: Time manipulation</a>.</p><h2 id="q9-my-tests-fail-randomly-flaky" tabindex="-1">Q9: My tests fail randomly (flaky) <a class="header-anchor" href="#q9-my-tests-fail-randomly-flaky" aria-label="Permalink to &quot;Q9: My tests fail randomly (flaky)&quot;">​</a></h2><p>A: Check in order:</p><ol><li>A previous anvil instance may still be running (<code>lsof -iTCP:8545</code>)</li><li><code>.env.local</code> may hold stale contract addresses</li><li>Polling-based assertions can often be deterministically replaced via <code>waitForChainState</code></li></ol><h2 id="q10-officially-supported-scope" tabindex="-1">Q10: Officially supported scope <a class="header-anchor" href="#q10-officially-supported-scope" aria-label="Permalink to &quot;Q10: Officially supported scope&quot;">​</a></h2><p>A: kiwa supports headless Chromium + standard wallet APIs only. Browser-extension UI driving (MetaMask, etc.), Firefox / Safari, and mobile WebViews are out of scope.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="https://github.com/cardene777/kiwa/issues" target="_blank" rel="noreferrer">GitHub Issues</a></li><li><a href="./concepts/README">Concepts</a></li><li><a href="./cookbook/README">Cookbook</a></li></ul>',27)])])}const u=a(o,[["render",n]]);export{k as __pageData,u as default};
